<template>
  <section class="mx-auto flex w-full max-w-md flex-col gap-4 p-1">
    <PageTitle title="Work Shift" />

    <Alert
      v-if="isPaused"
      variant="warning"
      data-testid="shift-break-banner"
      class="flex items-center gap-4 bg-card flex-1"
    >
      <div class="flex flex-col gap-2">
        <div class="flex items-center gap-2">
          <CoffeeIcon class="size-5" />
          <AlertTitle class="mb-0 leading-5">On break — tracking is paused</AlertTitle>
        </div>
        <AlertDescription class="mb-0 flex flex-wrap items-center justify-between gap-3 leading-5">
          <span>Break time: {{ timer.breakFormattedDuration.value }}</span>
          <Button
            size="sm"
            variant="outline-warning"
            class="gap-1.5"
            :disabled="pausing"
            :loading="pausing"
            @click="handlePauseResumeClick"
          >
            <PlayIcon class="size-4" />
            Resume work shift
          </Button>
        </AlertDescription>
      </div>
    </Alert>

    <WorkShiftHoursHero
      v-if="isSubcontractorCanvasser"
      :net-hours="earningProgress?.net_hours ?? 0"
      :last-interaction-timestamp="earningProgress?.last_interaction_timestamp ?? null"
      :is-paused="isPaused"
    />
    <WorkShiftEarningsHero v-else :earning-progress="processedEarningProgress" :is-paused="isPaused" />

    <WorkShiftMetaCard
      v-if="project?.id"
      :project-id="project.id"
      :project-name="project.name"
      :started-at="startedAtLabel"
      :show-break="!isSubcontractorCanvasser"
      :paid-break-hours-left="earningProgress?.paid_break_hours_left ?? null"
    />

    <WorkShiftActions
      :is-paused="isPaused"
      :show-break="!isSubcontractorCanvasser"
      :pausing="pausing"
      :syncing="syncing"
      :ending="ending"
      :is-uploading="uploadProgress.isUploading"
      :unsynced-count="unsyncedShiftIds.length"
      @pause-resume="handlePauseResumeClick"
      @sync="syncNow"
      @end="stopTracking"
    />

    <Alert
      v-if="isTracking && startStatus !== 'success'"
      variant="destructive"
      class="flex items-center gap-4 bg-card flex-1"
    >
      <div class="flex flex-col gap-2">
        <div class="flex items-center gap-2">
          <TriangleAlert class="size-5" />
          <AlertTitle class="mb-0 leading-5">Something went wrong</AlertTitle>
        </div>
        <AlertDescription class="mb-0 leading-5">
          Something went wrong during the start of your work shift. The necessary data might be lost. Try to restart the
          work shift or report a bug.
        </AlertDescription>
      </div>
    </Alert>

    <Alert v-if="permissionsMissing" variant="destructive" class="flex items-center gap-4 bg-card flex-1">
      <div class="flex flex-col gap-2">
        <div class="flex items-center gap-2">
          <TriangleAlert class="size-5" />
          <AlertTitle class="mb-0 leading-5">Permissions changed</AlertTitle>
        </div>
        <AlertDescription class="mb-0 leading-5">
          You or your phone's operating system revoked some permissions needed to continue the work shift. Please go to
          settings and allow the permissions listed below.
        </AlertDescription>
      </div>
    </Alert>

    <UnsyncedShiftAlert v-if="hasUnsyncedRecords" :count="unsyncedShiftIds.length" :syncing="syncing" @sync="syncNow" />

    <PermissionToggles v-if="permissionsMissing" :project="project" />

    <AudioRestrictionBanner
      :enabled="isTracking && project?.audio_recording_config?.permission === 'full_recording_with_restricted_area'"
    />
  </section>
</template>

<script setup lang="ts">
import { TriangleAlert, CoffeeIcon, PlayIcon } from 'lucide-vue-next';
import type { WorkShiftEarningProgressResponse } from '~/client';

useSeoMeta({
  title: 'Work Shift',
  description: 'Active work shift tracking.',
});

definePageMeta({
  roles: ['canvasser', 'subcontractor_canvasser'],
  platform: 'mobile',
  middleware: ['shift-guard'],
  backLabel: 'work shift',
});

import { Dialog } from '@capacitor/dialog';
import { checkForUnsyncedData } from '~/utils/useDb';
import { processError } from '~/utils/mobile/processError';
import { useWorkShiftProject } from '~/composables/mobile/projects/useWorkShiftProject';
import { useMobileRuntimeState } from '~/composables/mobile/useMobileRuntimeState';

const route = useRoute('shift-id');
const { isSubcontractorCanvasser } = useUserRole();

const {
  isPaused,
  isTracking,
  unsyncedShiftIds,
  startStatus,
  hasNetworkError,
  permissionsMissing,
  lastUploadHadErrors,
  uploadProgress,
} = useMobileRuntimeState();
const { stop, timer, syncDataWithProgress, resume, pause } = useNuxtApp().$mobile;
const { project, load } = useWorkShiftProject();

const workShiftId = computed(() => route.params.id);
// A paused shift is still ongoing (the endpoint only 404s on finished shifts), so keep the
// query enabled while paused — otherwise pausing before the first fetch drops the hero to
// its fallback. pause() flips isTracking off, hence the explicit isPaused.
const shiftOngoing = computed(() => isTracking.value || isPaused.value);
const { data: earningProgress } = useWorkShiftEarningProgressQuery(workShiftId, shiftOngoing);

const pausing = ref(false);
const syncing = ref(false);
const ending = ref(false);
const hasUnsyncedRecords = computed(() => unsyncedShiftIds.value.length > 0);

const startedAtLabel = computed(() => {
  if (!timer.shiftStartTime.value) return '—';
  return new Date(timer.shiftStartTime.value).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
});

// Shown while the earning_progress query is loading or has failed (404 right after start,
// finished shift, network). Keeps the hero rendered with zeros; controls work regardless.
const fallbackEarningProgress: WorkShiftEarningProgressResponse = {
  net_hours: 0,
  current_earned: null,
  current_pay_rate: null,
  increased_pay_rate: null,
  increased_pay_rate_threshold_in_hours: null,
  paid_break_hours_left: 0,
  last_interaction_timestamp: null,
};

const processedEarningProgress = computed(() => earningProgress.value ?? fallbackEarningProgress);

const stopTracking = async () => {
  try {
    ending.value = true;
    const { value } = await Dialog.confirm({
      title: 'Finish the work shift?',
      message:
        "Are you sure you'd like to end the work shift? If you want to take a small break just use the 'Take a break' button.",
    });
    if (value) {
      await stop();
      await navigateTo({ name: 'shift' }, { replace: true });
    }
  } catch (e: any) {
    if (!hasNetworkError.value) {
      processError(e);
    }
  } finally {
    ending.value = false;
  }
};

const handlePauseResumeClick = async () => {
  pausing.value = true;
  try {
    if (isPaused.value) {
      await resume();
    } else {
      await pause();
    }
  } catch (e: any) {
    processError(e);
  } finally {
    pausing.value = false;
  }
};

const syncNow = async () => {
  if (syncing.value) return;
  if (servingOffline.value) {
    showOfflineToastError();
    return;
  }
  syncing.value = true;
  try {
    await syncDataWithProgress();
    if (servingOffline.value) {
      showOfflineToastError();
    } else if (lastUploadHadErrors.value) {
      showToastError('Some data failed to upload. Please try again.');
    } else {
      showToastSuccess('All data uploaded successfully');
    }
  } catch (e: any) {
    if (!hasNetworkError.value) {
      processError(e);
    }
  } finally {
    syncing.value = false;
  }
};

watch(hasNetworkError, (isError, wasError) => {
  if (wasError && !isError && (isTracking.value || hasUnsyncedRecords.value)) {
    syncNow();
  }
});

watch(isTracking, (tracking) => {
  if (!tracking && !ending.value && !isPaused.value) {
    navigateTo({ name: 'shift' }, { replace: true });
  }
});

onMounted(async () => {
  await timer.ensureInitialised();
  await load();
  unsyncedShiftIds.value = await checkForUnsyncedData();
});
</script>
