<template>
  <Transition name="slide-down">
    <div v-if="showBanner" class="bg-background border border-border rounded-lg px-4 py-3 flex items-center gap-3">
      <Info class="h-5 w-5 flex-shrink-0 text-blue-500" />
      <div class="flex-1 min-w-0">
        <p class="text-sm font-medium text-foreground">{{ bannerTitle }}</p>
        <p v-if="bannerSubtitle" class="text-xs text-muted-foreground">{{ bannerSubtitle }}</p>
      </div>
    </div>
  </Transition>
  <div v-if="debugMode" class="text-xs text-muted-foreground mt-2 p-2 bg-muted rounded">
    <p>Debug: projectId={{ projectId }}</p>
    <p>
      Location:
      {{ location ? `${location.latitude.toFixed(6)}, ${location.longitude.toFixed(6)}` : 'waiting...' }}
    </p>
    <p>
      Zones: {{ zones?.zones?.value?.length ?? 0 }}, Restricted:
      {{ zones?.status?.value?.isRestricted ? 'YES' : 'NO' }}, isRestricted: {{ isRestricted }}, showBanner:
      {{ showBanner }}
    </p>
  </div>
</template>

<script setup lang="ts">
import { Info } from 'lucide-vue-next';
import { useAudioRestrictionZones } from '~/composables/mobile/audio/useAudioRestrictionZones';
import { useWorkShiftProject } from '~/composables/mobile/projects/useWorkShiftProject';
import { useCurrentLocation } from '~/composables/mobile/useCurrentLocation';
import { AUDIO_RECORDING_PERMISSION } from '~/types/mobile/geofencing';

const debugMode = ref(false);

const { project } = useWorkShiftProject();
const projectId = computed(() => project.value?.id ?? '');

const { location } = useCurrentLocation();

const zones = computed(() => {
  const id = project.value?.id;
  const perm = project.value?.audio_recording_config?.permission;
  if (!id || perm !== AUDIO_RECORDING_PERMISSION.FULL_RECORDING_WITH_RESTRICTED_AREA) return null;
  return useAudioRestrictionZones(id);
});

watchEffect(() => {
  if (location.value && zones.value) {
    void zones.value.ensureZonesLoaded(location.value);
  }
});

const isRestricted = computed(() =>
  location.value && zones.value ? zones.value.checkRestriction(location.value).isRestricted : false
);

const showBanner = computed(() => isRestricted.value);

const bannerTitle = 'Note-taking paused in this area';
const bannerSubtitle = 'Note-taking will resume when you leave this zone';
</script>

<style scoped>
.slide-down-enter-active,
.slide-down-leave-active {
  transition: all 0.3s ease;
}

.slide-down-enter-from,
.slide-down-leave-to {
  opacity: 0;
  transform: translateY(-10px);
}
</style>
