<template>
  <div class="flex items-center justify-between gap-3 rounded-xl border px-4 py-3">
    <div class="flex flex-col gap-1">
      <span v-if="showWorkedHours" class="flex items-center gap-1.5 text-sm font-medium">
        <ClockIcon class="size-4 shrink-0" />
        {{ formatHours(netHours) }} worked
      </span>
      <span
        class="flex items-center gap-1.5"
        :class="showWorkedHours ? 'text-xs text-muted-foreground' : 'text-sm font-medium'"
      >
        <HistoryIcon :class="showWorkedHours ? 'size-3 shrink-0' : 'size-4 shrink-0'" />
        {{ lastSyncLabel }}
      </span>
    </div>
    <Popover>
      <PopoverTrigger>
        <CircleQuestionMarkIcon class="w-5 h-5 text-muted-foreground" />
      </PopoverTrigger>
      <PopoverContent side="top" class="text-wrap max-w-72 w-fit p-4 z-40">
        {{ description }}
      </PopoverContent>
    </Popover>
  </div>
</template>

<script setup lang="ts">
import { ClockIcon, HistoryIcon, CircleQuestionMarkIcon } from 'lucide-vue-next';

interface Props {
  netHours: number;
  lastInteractionTimestamp: string | null;
  description?: string;
  showWorkedHours?: boolean;
}

const props = withDefaults(defineProps<Props>(), {
  description:
    'Your worked time and earnings are calculated based on the interactions from your canvassing app that have been synced so far',
  showWorkedHours: true,
});

const lastSyncLabel = computed(() => {
  if (!props.lastInteractionTimestamp) return 'Waiting for canvassing app data';
  const time = new Date(props.lastInteractionTimestamp).toLocaleTimeString([], {
    hour: '2-digit',
    minute: '2-digit',
  });
  return `Last synced interaction at ${time}`;
});
</script>
