import type { WorkShiftEarningProgressResponse } from '~/client';

export interface EarningProgressView {
  /** Whether money has been earned (false for subcontractors / no pay rate). */
  hasEarnings: boolean;
  /** Net hours reached or passed the increased-rate threshold. */
  isUnlocked: boolean;
  /** Rate applied right now: increased once unlocked, else the normal rate. null when no pay rate. */
  currentRate: number | null;
  /** Progress toward the increased-rate threshold, 0–100. */
  payRateProgress: number;
  /** Hours remaining until the increased rate unlocks (floored at 0). */
  hoursToUnlock: number;
}

export function buildEarningProgressView(progress: WorkShiftEarningProgressResponse): EarningProgressView {
  const netHours = progress.net_hours ?? 0;
  const threshold = progress.increased_pay_rate_threshold_in_hours ?? 0;
  const hasThreshold = threshold > 0;

  const isUnlocked = hasThreshold && netHours >= threshold;

  const currentRate = isUnlocked ? progress.increased_pay_rate : progress.current_pay_rate;

  const payRateProgress = isUnlocked ? 100 : hasThreshold ? Math.min(100, (netHours / threshold) * 100) : 0;

  const hoursToUnlock = hasThreshold ? Math.max(0, threshold - netHours) : 0;

  return {
    hasEarnings: progress.current_earned != null,
    isUnlocked,
    currentRate: currentRate ?? null,
    payRateProgress,
    hoursToUnlock,
  };
}
