import { getWorkShiftEarningProgress, type WorkShiftEarningProgressResponse } from '~/client';

export function useWorkShiftEarningProgressQuery(workShiftId: Ref<string | undefined>, enabled?: Ref<boolean>) {
  return useQuery({
    key: () => ['workshift-earning-progress', workShiftId.value ?? ''],
    query: (): Promise<WorkShiftEarningProgressResponse> =>
      getWorkShiftEarningProgress({
        composable: '$fetch',
        path: { work_shift_id: workShiftId.value as string },
      }),
    enabled: () => Boolean(workShiftId.value) && (enabled ? enabled.value : true),
    staleTime: Infinity, // no interval polling
    refetchOnMount: 'always', // force a fresh fetch on every (re)mount; respects `enabled`
  });
}
