<template>
  <div class="flex flex-col gap-3">
    <Button
      v-if="showBreak"
      class="h-14 w-full gap-2 text-base"
      :variant="isPaused ? 'success' : 'outline-warning'"
      size="lg"
      :disabled="pausing || ending"
      @click="$emit('pause-resume')"
    >
      <PlayIcon v-if="isPaused" class="size-5" />
      <CoffeeIcon v-else class="size-5" />
      {{ isPaused ? 'Resume work shift' : 'Take a break' }}
    </Button>

    <WorkShiftUploadProgress />

    <template v-if="!isUploading">
      <Button
        variant="outline"
        class="h-12 w-full gap-2"
        :disabled="syncing || ending"
        :loading="syncing"
        @click="$emit('sync')"
      >
        <RefreshCwIcon class="size-4" />
        {{ syncing ? 'Syncing…' : 'Sync now' }}
      </Button>
      <p v-if="unsyncedCount > 0" class="text-center text-xs text-amber-600">
        {{ unsyncedCount }} {{ unsyncedCount === 1 ? 'item' : 'items' }} waiting to upload
      </p>
    </template>

    <Separator class="my-1" />

    <Button
      class="h-12 w-full gap-2"
      variant="outline-destructive"
      :disabled="ending"
      :loading="ending"
      @click="$emit('end')"
    >
      <LogOutIcon class="size-4" />
      End shift
    </Button>
    <p class="text-center text-xs text-muted-foreground">Uploads any remaining data, then ends tracking.</p>
  </div>
</template>

<script setup lang="ts">
import { CoffeeIcon, PlayIcon, RefreshCwIcon, LogOutIcon } from 'lucide-vue-next';

defineProps<{
  isPaused: boolean;
  showBreak: boolean;
  pausing: boolean;
  syncing: boolean;
  ending: boolean;
  isUploading: boolean;
  unsyncedCount: number;
}>();

defineEmits<{
  'pause-resume': [];
  sync: [];
  end: [];
}>();
</script>
