<template>
  <Card>
    <CardContent class="flex flex-col gap-3 p-4 text-sm">
      <NuxtLink
        :to="{ name: 'projects-id', params: { id: projectId } }"
        class="flex items-center justify-between gap-2"
      >
        <span class="flex items-center gap-1.5 font-medium">
          <NotebookTextIcon class="size-4 shrink-0" />
          {{ projectName }}
        </span>
        <ChevronRightIcon class="size-4 shrink-0 text-muted-foreground" />
      </NuxtLink>
      <Separator />
      <div class="flex items-center justify-between gap-3 text-muted-foreground">
        <span class="flex items-center gap-1.5">
          <ClockIcon class="size-3.5 shrink-0" />
          Started
          <span class="font-medium text-foreground">{{ startedAt }}</span>
        </span>
        <span
          v-if="showBreak && paidBreakHoursLeft != null"
          class="flex items-center gap-1.5"
          :class="paidBreakMinutesLeft === 0 ? 'text-amber-600' : ''"
        >
          <CoffeeIcon class="size-3.5 shrink-0" />
          Paid break left
          <span class="font-medium" :class="paidBreakMinutesLeft === 0 ? '' : 'text-foreground'">
            {{ paidBreakMinutesLeft }}m
          </span>
        </span>
      </div>
    </CardContent>
  </Card>
</template>

<script setup lang="ts">
import { ClockIcon, CoffeeIcon, ChevronRightIcon, NotebookTextIcon } from 'lucide-vue-next';

const props = defineProps<{
  projectId: string;
  projectName: string;
  startedAt: string;
  showBreak: boolean;
  paidBreakHoursLeft?: number | null;
}>();

const paidBreakMinutesLeft = computed(() => Math.round((props.paidBreakHoursLeft ?? 0) * 60));
</script>
